negativeExample:
package test;

import org.osgi.framework.Bundle;
import org.eclipse.core.runtime.ILog;
import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;

class AnotherLogHolder {
    public ILog getLog(Bundle b) { return null; }
}

public class MyClass {
    public void myMethod(Bundle bundle) {
        if (bundle == null) return;
        IStatus status = new Status(IStatus.INFO, bundle.getSymbolicName(), "Test message");
        // Should not match as it's not Platform.getLog
        new AnotherLogHolder().getLog(bundle).log(status);
        // Already using the new method, should not be changed
        ILog myLog = ILog.of(bundle);
        myLog.log(status);
    }
}
